/// A choice made by the user when prompted with a new update.
enum SPUUserUpdateChoice {
  /// Dismisses the update and skips being notified of it in the future.
  SPUUserUpdateChoiceSkip(0),

  /// Downloads (if needed) and installs the update.
  SPUUserUpdateChoiceInstall(1),

  /// Dismisses the update until Sparkle reminds the user of it at a later time.
  SPUUserUpdateChoiceDismiss(2);

  final int value;
  const SPUUserUpdateChoice(this.value);

  static SPUUserUpdateChoice fromValue(int value) => switch (value) {
    0 => SPUUserUpdateChoiceSkip,
    1 => SPUUserUpdateChoiceInstall,
    2 => SPUUserUpdateChoiceDismiss,
    _ => throw ArgumentError('Unknown value for SPUUserUpdateChoice: $value'),
  };
}

/// Describes the current stage an update is undergoing.
enum SPUUserUpdateStage {
  /// The update has not been downloaded.
  SPUUserUpdateStageNotDownloaded(0),

  /// The update has already been downloaded but not begun installing.
  SPUUserUpdateStageDownloaded(1),

  /// The update has already been downloaded and began installing in the background.
  SPUUserUpdateStageInstalling(2);

  final int value;
  const SPUUserUpdateStage(this.value);

  static SPUUserUpdateStage fromValue(int value) => switch (value) {
    0 => SPUUserUpdateStageNotDownloaded,
    1 => SPUUserUpdateStageDownloaded,
    2 => SPUUserUpdateStageInstalling,
    _ => throw ArgumentError('Unknown value for SPUUserUpdateStage: $value'),
  };
}

